public class Main {
    static final class BankAccount {
        private long balanceCents;
        void deposit(long cents) {
            if (cents <= 0) throw new IllegalArgumentException("Deposit must be positive");
            balanceCents = Math.addExact(balanceCents, cents);
        }
        void withdraw(long cents) {
            if (cents <= 0 || cents > balanceCents) throw new IllegalArgumentException("Invalid withdrawal");
            balanceCents -= cents;
        }
        long balanceCents() { return balanceCents; }
    }
    public static void main(String[] args) {
        BankAccount account = new BankAccount();
        account.deposit(2500);
        account.withdraw(700);
        System.out.println("Balance: " + account.balanceCents() + " cents");
    }
}
